SOURCE_INPUTS={'sheeter': {'bytes': 29646, 'sha256': 'a87b64138a54aba7e9d20f6bda8a64ad54798ac0060e8e1e7393b8c98f8d8391', 'compressed': ''}, 'table': {'bytes': 30478, 'sha256': 'b4880f9c24dda10b566fa215c394295b6522a8ad448486918c591826480c09d8', 'compressed': ''}, 'mixer': {'bytes': 22245, 'sha256': '0df8caaa6baeb9a4a447a03a7f77c3238a5298a61e74093c6da24b37afde5b91', 'compressed': ''}}
